import{_ as t,o,c as a,a5 as r}from"./chunks/framework.BfQ7H7Qx.js";const g=JSON.parse('{"title":"Video Space Nonlinear Editor, Conversational Auto-Edit Agent & Containerized Claude FFmpeg Worker","description":"","frontmatter":{},"headers":[],"relativePath":"feature/modules/06-ai-media-and-video-studio/video-space-and-claude-edit-worker/spec.md","filePath":"feature/modules/06-ai-media-and-video-studio/video-space-and-claude-edit-worker/spec.md"}'),i={name:"feature/modules/06-ai-media-and-video-studio/video-space-and-claude-edit-worker/spec.md"};function d(n,e,s,c,l,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Category Index</a> · <a href="./../../README.html">← Modules Master Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="video-space-nonlinear-editor-conversational-auto-edit-agent-containerized-claude-ffmpeg-worker" tabindex="-1">Video Space Nonlinear Editor, Conversational Auto-Edit Agent &amp; Containerized Claude FFmpeg Worker <a class="header-anchor" href="#video-space-nonlinear-editor-conversational-auto-edit-agent-containerized-claude-ffmpeg-worker" aria-label="Permalink to &quot;Video Space Nonlinear Editor, Conversational Auto-Edit Agent &amp; Containerized Claude FFmpeg Worker&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Module Slug</strong></td><td style="text-align:left;"><code>video-space-and-claude-edit-worker</code></td></tr><tr><td style="text-align:left;"><strong>Category</strong></td><td style="text-align:left;"><code>06-ai-media-and-video-studio</code> — AI Commercial Image, Product Video &amp; Conversational Video Studio</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner, Manager, Creator</code></td></tr><tr><td style="text-align:left;"><strong>Consolidated Feature Scopes</strong></td><td style="text-align:left;"><code>video-space</code>, <code>video-space-conversational-edits</code>, <code>server-video-editor</code>, <code>edit-video-direct</code>, <code>video-auto-edit-agent</code>, <code>video-edit-claude-container</code>, <code>video-edit-guide-library</code></td></tr><tr><td style="text-align:left;"><strong>Aligned SRS Domains</strong></td><td style="text-align:left;"><a href="./../../../srs/06-ai-features/3-7-11-generate-video/spec.html">FR 3.7.11 — Generate Video</a> · <a href="./../../../srs/06-ai-features/3-7-12-export-file/spec.html">FR 3.7.12 — Export File</a> · <a href="./../../../srs/05-content-task-workflow/README.html">3.6 Content &amp; Workflow</a></td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified</td></tr></tbody></table><h2 id="_1-objective-architectural-motivation" tabindex="-1">1. Objective &amp; Architectural Motivation <a class="header-anchor" href="#_1-objective-architectural-motivation" aria-label="Permalink to &quot;1. Objective &amp; Architectural Motivation&quot;">​</a></h2><p>Unify <strong>Video Space</strong> (<code>/workspaces/:workspaceId/video-space</code> — <code>VideoProjectController</code>), <strong>Conversational AI Video Editing &amp; Project Memory</strong> (<code>VideoAutoEditController</code>, <code>VideoAutoEditMemoryController</code>), <strong>Direct Server FFmpeg Runtime</strong> (<code>server_video_edit.py</code> / <code>edit-video-direct</code>), <strong>Sandboxed Containerized Claude Video-Edit Worker</strong> (<code>video_edit_worker.py</code> + <code>InternalVideoEditController</code>), and <strong>On-Demand Video Editing Guide Skills</strong> (<code>video-edit-guide-library</code>).</p><h2 id="_2-user-stories" tabindex="-1">2. User Stories <a class="header-anchor" href="#_2-user-stories" aria-label="Permalink to &quot;2. User Stories&quot;">​</a></h2><ul><li>As a <code>Creator</code>, <code>Manager</code>, or <code>Owner</code>, I want an integrated <strong>Video Space</strong> timeline workspace where I can upload multi-clip project assets to S3, instruct an AI Video Editing Agent in natural Vietnamese/English (e.g., <em>&#39;cắt bỏ đoạn im lặng đầu clip, chèn phụ đề nhịp nhanh, xuất 9:16 cho TikTok&#39;</em>), persist project style memory across edits, and export rendered MP4s back to Tasks or the Material Repository.</li></ul><h2 id="_3-consolidated-acceptance-criteria" tabindex="-1">3. Consolidated Acceptance Criteria <a class="header-anchor" href="#_3-consolidated-acceptance-criteria" aria-label="Permalink to &quot;3. Consolidated Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Video Space Project &amp; Multipart Media Runtime (<code>video-space</code>, <code>2026-11-09-video-space-runtime-foundation.sql</code>):</strong> <code>VideoProjectController</code> (<code>/api/v1/workspaces/{workspaceId}/video-projects</code>, <code>/{projectId}/edit-plans</code>, <code>/{projectId}/media/{assetId}/upload-session|upload-complete|upload-abort</code>) persists nonlinear project state in MongoDB (<code>video_projects</code>, <code>video_project_assets</code>, <code>video_project_upload_sessions</code>) with S3 quota reservations.</li><li><strong>Conversational Edits &amp; Persistent Style Memory (<code>video-space-conversational-edits</code>, <code>video-auto-edit-agent</code>):</strong> <code>VideoAutoEditController</code> (<code>POST/GET /video-projects/{projectId}/auto-edits</code>) and <code>VideoAutoEditMemoryController</code> (<code>GET/PUT .../auto-edit-memory</code>) translate conversational chat turns into structured edit plans (<code>video_edit_planner.py</code>) while remembering brand pacing, font, and aspect-ratio preferences.</li><li><strong>Server Video Editor &amp; Containerized Claude Worker (<code>server-video-editor</code>, <code>edit-video-direct</code>, <code>video-edit-claude-container</code>):</strong> <code>app/api/v1/endpoints/server_video_edit.py</code> and <code>app/video_edit_worker.py</code> run FFmpeg / Python editing tools (<code>tools/video-edit/edit.py</code>) inside an isolated container sandbox, fetching authorized source clips and uploading finished renders via <code>InternalVideoEditController</code> (<code>/api/v1/internal/video-edits/{jobId}/sources/{assetId}</code> &amp; <code>/output-session|output-complete|output-abort</code>).</li><li><strong>On-Demand Video Editing Guide Library (<code>video-edit-guide-library</code>):</strong> <code>tools/video-edit/package_guides.py</code> provides modular, token-efficient editing recipes (jump-cut pacing, burned-in captions, audio ducking, color Lut, aspect-ratio reframing) loaded on demand by the agent rather than bloating every prompt.</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> Every user-facing string, tooltip, dialog prompt, status badge, and error banner uses key-parallel translations (<code>videoSpace.{timeline,chatAgent,memory,upload,export,guides}.*</code> in <code>src/i18n/locales/{vi,en}/videoSpace.json</code>) on <code>brandhub-web</code> and <code>tr()</code> (<code>en.json</code> + <code>vi/common.json</code>) on <code>brandhub-mobile-app</code> with zero hardcoded Vietnamese or English strings in JSX/TSX.</li><li><strong>Light &amp; Dark Mode Compliance:</strong> All surfaces, drawers, badges, charts, and interactive controls use semantic CSS variables / Tailwind <code>dark:</code> variants on Web and <code>useAppPreferences().palette</code> tokens on Mobile, achieving WCAG AA contrast in both Light and Dark themes.</li></ol><h2 id="_4-ui-ux-surfaces-lifecycle-states" tabindex="-1">4. UI / UX Surfaces &amp; Lifecycle States <a class="header-anchor" href="#_4-ui-ux-surfaces-lifecycle-states" aria-label="Permalink to &quot;4. UI / UX Surfaces &amp; Lifecycle States&quot;">​</a></h2><ul><li><strong>Web Surfaces (<code>brandhub-web</code>):</strong> <code>pages/video-space/index.tsx</code>, <code>pages/video-space/components/VideoSpaceWorkspace.tsx</code></li><li><strong>Mobile Surfaces (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/more/QuickReelStudioScreen.tsx</code> (<code>POST /materials/reel-studio/auto-edit</code>), <code>src/services/videoSpaceService.ts</code></li><li><strong>UI States:</strong><ul><li><strong>Loading / Streaming:</strong> Deterministic skeleton placeholders, progress bars, and disabled submit buttons preventing duplicate requests.</li><li><strong>Empty / Onboarding:</strong> Contextual empty state with localized call-to-action and zero fabricated mock fallback data.</li><li><strong>Active / Realtime Sync:</strong> Scoped <code>TanStack Query</code> cache updates + WebSocket/SSE/polling synchronization where applicable.</li><li><strong>Error / Conflict Recovery:</strong> Actionable localized error banners (<code>400/403/404/409/429/503</code>) preserving unsaved user input.</li></ul></li></ul><h2 id="_5-api-messaging-protocol-contract" tabindex="-1">5. API, Messaging &amp; Protocol Contract <a class="header-anchor" href="#_5-api-messaging-protocol-contract" aria-label="Permalink to &quot;5. API, Messaging &amp; Protocol Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Route / Channel / Filter</th><th style="text-align:left;">Auth / Scope</th><th style="text-align:left;">Service &amp; Handler</th></tr></thead><tbody><tr><td style="text-align:left;"><code>GET/PUT/POST /api/v1/workspaces/{workspaceId}/video-projects/**</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator</code>)</td><td style="text-align:left;"><code>VideoProjectController</code> -&gt; project state, edit plans &amp; S3 asset upload sessions</td></tr><tr><td style="text-align:left;"><code>POST/GET /api/v1/workspaces/{workspaceId}/video-projects/{projectId}/auto-edits/**</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator</code>)</td><td style="text-align:left;"><code>VideoAutoEditController</code> -&gt; conversational AI edit jobs &amp; rendered MP4 stream</td></tr><tr><td style="text-align:left;"><code>GET/PUT /api/v1/workspaces/{workspaceId}/video-projects/{projectId}/auto-edit-memory</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator</code>)</td><td style="text-align:left;"><code>VideoAutoEditMemoryController</code> -&gt; per-project editing style memory</td></tr><tr><td style="text-align:left;"><code>GET/POST /api/v1/internal/video-edits/{jobId}/**</code></td><td style="text-align:left;"><code>X-Internal-Service-Key</code></td><td style="text-align:left;"><code>InternalVideoEditController</code> &lt;- containerized worker source fetch &amp; S3 output commit</td></tr></tbody></table><h2 id="_6-error-handling-security-edge-cases" tabindex="-1">6. Error Handling, Security &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-security-edge-cases" aria-label="Permalink to &quot;6. Error Handling, Security &amp; Edge Cases&quot;">​</a></h2><ul><li><strong>Worker Crash or Invalid FFmpeg Filter Graph:</strong> Isolated per-job staging directory (<code>scripts/stage_video_edit_context.py</code>) cleans up temporary disk artifacts and calls <code>/output-abort</code> so failed edits never leak S3 multipart parts or storage quota.</li><li><strong>Path Traversal / Arbitrary Shell Escape Guard:</strong> Worker mounts only job-scoped scratch directories and accesses media exclusively via signed <code>InternalVideoEditController</code> sessions.</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Aligned SRS Functional Requirements:</strong> <a href="./../../../srs/06-ai-features/3-7-11-generate-video/spec.html">FR 3.7.11 — Generate Video</a> · <a href="./../../../srs/06-ai-features/3-7-12-export-file/spec.html">FR 3.7.12 — Export File</a> · <a href="./../../../srs/05-content-task-workflow/README.html">3.6 Content &amp; Workflow</a></li><li><strong>BA &amp; Architecture References:</strong> <a href="./../../../../ba/06-ai-features.html">BA 06 AI Features</a> · <a href="./../../../../ba/10-roles-permissions-matrix.html">Roles &amp; Permissions Matrix</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Production code verified across backend, AI/publisher workers, Web, and Mobile; <code>vi.json</code> + <code>en.json</code> parity verified; Light/Dark mode audited; all automated verification suites in <a href="./test.html">test.md</a> passing.</li><li><strong>Out of Scope:</strong> De-scoped SRS items (livestream features, subscription plan downgrades, PayOS/VNPay/Stripe gateways, Zalo OA publishing, or copyright/plagiarism scanning).</li></ul>',19)])])}const m=t(i,[["render",d]]);export{g as __pageData,m as default};
